1	import { useQueryClient } from "@tanstack/react-query";
2	import { createContext, type ReactNode, useCallback, useContext, useMemo, useState } from "react";
3	import { clearAccessToken, getAccessToken } from "@/auth-state";
4	import { authServiceClient, refreshAccessToken, shortcutServiceClient, userServiceClient } from "@/connect";
5	import { userKeys } from "@/hooks/useUserQueries";
6	import type { Shortcut } from "@/types/proto/api/v1/shortcut_service_pb";
7	import type {
8	  User,
9	  UserSetting_GeneralSetting,
10	  UserSetting_TagsSetting,
11	  UserSetting_WebhooksSetting,
12	} from "@/types/proto/api/v1/user_service_pb";
13	
14	interface AuthState {
15	  currentUser: User | undefined;
16	  userGeneralSetting: UserSetting_GeneralSetting | undefined;
17	  userWebhooksSetting: UserSetting_WebhooksSetting | undefined;
18	  userTagsSetting: UserSetting_TagsSetting | undefined;
19	  shortcuts: Shortcut[];
20	  isInitialized: boolean;
21	  isLoading: boolean;
22	}
23	
24	interface AuthContextValue extends AuthState {
25	  initialize: () => Promise<void>;
26	  logout: () => Promise<void>;
27	  refetchSettings: () => Promise<void>;
28	  setCurrentUser: (user: User | undefined) => void;
29	}
30	
31	const AuthContext = createContext<AuthContextValue | null>(null);
32	
33	/** Settled auth state for a request with no valid session (init finished, not loading). */
34	const UNAUTHENTICATED_STATE: AuthState = {
35	  currentUser: undefined,
36	  userGeneralSetting: undefined,
37	  userWebhooksSetting: undefined,
38	  userTagsSetting: undefined,
39	  shortcuts: [],
40	  isInitialized: true,
41	  isLoading: false,
42	};
43	
44	export function AuthProvider({ children }: { children: ReactNode }) {
45	  const queryClient = useQueryClient();
46	  const [state, setState] = useState<AuthState>({
47	    currentUser: undefined,
48	    userGeneralSetting: undefined,
49	    userWebhooksSetting: undefined,
50	    userTagsSetting: undefined,
51	    shortcuts: [],
52	    isInitialized: false,
53	    isLoading: true,
54	  });
55	
56	  const fetchUserSettings = useCallback(async (userName: string) => {
57	    const [{ settings }, { shortcuts }] = await Promise.all([
58	      userServiceClient.listUserSettings({ parent: userName }),
59	      shortcutServiceClient.listShortcuts({ parent: userName }),
60	    ]);
61	
62	    const generalSetting = settings.find((s) => s.value.case === "generalSetting");
63	    const webhooksSetting = settings.find((s) => s.value.case === "webhooksSetting");
64	    const tagsSetting = settings.find((s) => s.value.case === "tagsSetting");
65	
66	    return {
67	      userGeneralSetting: generalSetting?.value.case === "generalSetting" ? generalSetting.value.value : undefined,
68	      userWebhooksSetting: webhooksSetting?.value.case === "webhooksSetting" ? webhooksSetting.value.value : undefined,
69	      userTagsSetting: tagsSetting?.value.case === "tagsSetting" ? tagsSetting.value.value : undefined,
70	      shortcuts,
71	    };
72	  }, []);
73	
74	  const initialize = useCallback(async () => {
75	    setState((prev) => ({ ...prev, isLoading: true }));
76	
77	    // Try to get or refresh the access token.
78	    // This handles PWA isolated storage scenarios (e.g., iOS Safari) where localStorage
79	    // may be empty but a valid HTTP-only refresh token cookie still exists.
80	    // getAccessToken() returns a cached token or loads from localStorage if valid.
81	    if (!getAccessToken()) {
82	      try {
83	        await refreshAccessToken();
84	      } catch {
85	        // Refresh failed - no valid session
86	      }
87	    }
88	
89	    // If we still don't have a token after refresh attempt, skip getCurrentUser call
90	    // to avoid unnecessary network request for unauthenticated users.
91	    if (!getAccessToken()) {
92	      setState(UNAUTHENTICATED_STATE);
93	      return;
94	    }
95	
96	    try {
97	      const { user: currentUser } = await authServiceClient.getCurrentUser({});
98	
99	      if (!currentUser) {
100	        clearAccessToken();
101	        setState(UNAUTHENTICATED_STATE);
102	        return;
103	      }
104	
105	      const settings = await fetchUserSettings(currentUser.name);
106	
107	      setState({
108	        currentUser,
109	        ...settings,
110	        isInitialized: true,
111	        isLoading: false,
112	      });
113	
114	      // Pre-populate React Query cache
115	      queryClient.setQueryData(userKeys.currentUser(), currentUser);
116	      queryClient.setQueryData(userKeys.detail(currentUser.name), currentUser);
117	    } catch (error) {
118	      console.error("Failed to initialize auth:", error);
119	      clearAccessToken();
120	      setState(UNAUTHENTICATED_STATE);
121	    }
122	  }, [fetchUserSettings, queryClient]);
123	
124	  const logout = useCallback(async () => {
125	    try {
126	      await authServiceClient.signOut({});
127	    } catch (error) {
128	      console.error("[AuthContext] Failed to sign out:", error);
129	    } finally {
130	      clearAccessToken();
131	      setState(UNAUTHENTICATED_STATE);
132	      queryClient.clear();
133	    }
134	  }, [queryClient]);
135	
136	  const refetchSettings = useCallback(async () => {
137	    const currentUserName = state.currentUser?.name;
138	    if (!currentUserName) {
139	      return;
140	    }
141	
142	    const settings = await fetchUserSettings(currentUserName);
143	    setState((prev) => {
144	      if (prev.currentUser?.name !== currentUserName) {
145	        return prev;
146	      }
147	      return { ...prev, ...settings };
148	    });
149	  }, [fetchUserSettings, state.currentUser?.name]);
150	
151	  // Sync the updated user to AuthContext and React Query cache after profile changes
152	  const setCurrentUser = useCallback(
153	    (user: User | undefined) => {
154	      const previousUser = queryClient.getQueryData<User>(userKeys.currentUser());
155	      setState((prev) => ({ ...prev, currentUser: user }));
156	      if (user) {
157	        queryClient.setQueryData(userKeys.currentUser(), user);
158	        queryClient.setQueryData(userKeys.detail(user.name), user);
159	      } else {
160	        queryClient.removeQueries({ queryKey: userKeys.currentUser(), exact: true });
161	        if (previousUser?.name) {
162	          queryClient.removeQueries({ queryKey: userKeys.detail(previousUser.name), exact: true });
163	        }
164	      }
165	    },
166	    [queryClient],
167	  );
168	
169	  // Memoize context value to prevent unnecessary re-renders of consumers
170	  const value = useMemo(
171	    () => ({
172	      ...state,
173	      initialize,
174	      logout,
175	      refetchSettings,
176	      setCurrentUser,
177	    }),
178	    [state, initialize, logout, refetchSettings, setCurrentUser],
179	  );
180	
181	  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
182	}
183	
184	export function useAuth() {
185	  const context = useContext(AuthContext);
186	  if (!context) {
187	    throw new Error("useAuth must be used within AuthProvider");
188	  }
189	  return context;
190	}
191	
192	// Convenience hook for just the current user
193	export function useCurrentUserFromAuth() {
194	  const { currentUser } = useAuth();
195	  return currentUser;
196	}
197

1	const STATE_STORAGE_KEY = "oauth_state";
2	const STATE_EXPIRY_MS = 10 * 60 * 1000; // 10 minutes
3	
4	export type OAuthFlowMode = "signin" | "link";
5	
6	interface OAuthState {
7	  state: string;
8	  identityProviderName: string;
9	  flowMode: OAuthFlowMode;
10	  timestamp: number;
11	  returnUrl?: string;
12	  linkingUserName?: string;
13	  codeVerifier?: string; // PKCE code_verifier
14	}
15	
16	// Generate a cryptographically secure random state value
17	function generateSecureState(): string {
18	  const array = new Uint8Array(32);
19	  crypto.getRandomValues(array);
20	  return Array.from(array, (byte) => byte.toString(16).padStart(2, "0")).join("");
21	}
22	
23	// Generate a cryptographically secure random code_verifier for PKCE (RFC 7636)
24	// Returns a URL-safe base64 string (43-128 characters)
25	function generateCodeVerifier(): string {
26	  const array = new Uint8Array(32); // 256 bits = 32 bytes
27	  crypto.getRandomValues(array);
28	  // Convert to base64url (URL-safe base64 without padding)
29	  return base64UrlEncode(array);
30	}
31	
32	// Generate code_challenge from code_verifier using SHA-256
33	async function generateCodeChallenge(codeVerifier: string): Promise<string> {
34	  const encoder = new TextEncoder();
35	  const data = encoder.encode(codeVerifier);
36	  const hash = await crypto.subtle.digest("SHA-256", data);
37	  return base64UrlEncode(new Uint8Array(hash));
38	}
39	
40	// Base64URL encoding (RFC 4648 base64url without padding)
41	function base64UrlEncode(buffer: Uint8Array): string {
42	  const base64 = btoa(String.fromCharCode(...buffer));
43	  return base64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
44	}
45	
46	// Store OAuth state and PKCE parameters in sessionStorage
47	// Returns state and optional codeChallenge for use in authorization URL
48	// PKCE is optional - if crypto APIs are unavailable (HTTP context), falls back to standard OAuth
49	export async function storeOAuthState(
50	  identityProviderName: string,
51	  flowMode: OAuthFlowMode,
52	  returnUrl?: string,
53	  linkingUserName?: string,
54	): Promise<{ state: string; codeChallenge?: string }> {
55	  const state = generateSecureState();
56	
57	  // Try to generate PKCE parameters if crypto.subtle is available (HTTPS/localhost)
58	  // Falls back to standard OAuth flow if unavailable (HTTP context)
59	  let codeVerifier: string | undefined;
60	  let codeChallenge: string | undefined;
61	
62	  try {
63	    // Check if crypto.subtle is available (requires secure context: HTTPS or localhost)
64	    if (typeof crypto !== "undefined" && crypto.subtle) {
65	      codeVerifier = generateCodeVerifier();
66	      codeChallenge = await generateCodeChallenge(codeVerifier);
67	    } else {
68	      console.warn(
69	        "PKCE not available: crypto.subtle requires HTTPS. Falling back to standard OAuth flow without PKCE. " +
70	          "For enhanced security, please access Memos over HTTPS.",
71	      );
72	    }
73	  } catch (error) {
74	    // If PKCE generation fails for any reason, fall back to standard OAuth
75	    console.warn("Failed to generate PKCE parameters, falling back to standard OAuth:", error);
76	    codeVerifier = undefined;
77	    codeChallenge = undefined;
78	  }
79	
80	  const stateData: OAuthState = {
81	    state,
82	    identityProviderName,
83	    flowMode,
84	    timestamp: Date.now(),
85	    returnUrl,
86	    linkingUserName,
87	    codeVerifier, // Store for later retrieval in callback (undefined if PKCE not available)
88	  };
89	
90	  try {
91	    sessionStorage.setItem(STATE_STORAGE_KEY, JSON.stringify(stateData));
92	  } catch (error) {
93	    console.error("Failed to store OAuth state:", error);
94	    throw new Error("Failed to initialize OAuth flow");
95	  }
96	
97	  return { state, codeChallenge };
98	}
99	
100	// Validate and retrieve OAuth state from storage (CSRF protection)
101	// Returns identityProviderName, flowMode, returnUrl, linkingUserName, and codeVerifier for PKCE
102	export function validateOAuthState(
103	  stateParam: string,
104	): { identityProviderName: string; flowMode: OAuthFlowMode; returnUrl?: string; linkingUserName?: string; codeVerifier?: string } | null {
105	  try {
106	    const storedData = sessionStorage.getItem(STATE_STORAGE_KEY);
107	    if (!storedData) {
108	      console.error("No OAuth state found in storage");
109	      return null;
110	    }
111	
112	    const stateData: OAuthState = JSON.parse(storedData);
113	
114	    // Check if state has expired
115	    if (Date.now() - stateData.timestamp > STATE_EXPIRY_MS) {
116	      console.error("OAuth state has expired");
117	      sessionStorage.removeItem(STATE_STORAGE_KEY);
118	      return null;
119	    }
120	
121	    // Validate state matches (CSRF protection)
122	    if (stateData.state !== stateParam) {
123	      console.error("OAuth state mismatch - possible CSRF attack");
124	      sessionStorage.removeItem(STATE_STORAGE_KEY);
125	      return null;
126	    }
127	
128	    // State is valid, clean up and return data
129	    sessionStorage.removeItem(STATE_STORAGE_KEY);
130	    return {
131	      identityProviderName: stateData.identityProviderName,
132	      flowMode: stateData.flowMode || "signin",
133	      returnUrl: stateData.returnUrl,
134	      linkingUserName: stateData.linkingUserName,
135	      codeVerifier: stateData.codeVerifier, // Return PKCE code_verifier
136	    };
137	  } catch (error) {
138	    console.error("Failed to validate OAuth state:", error);
139	    sessionStorage.removeItem(STATE_STORAGE_KEY);
140	    return null;
141	  }
142	}
143	
144	// Clean up expired OAuth states (call on app init)
145	export function cleanupExpiredOAuthState(): void {
146	  try {
147	    const storedData = sessionStorage.getItem(STATE_STORAGE_KEY);
148	    if (!storedData) {
149	      return;
150	    }
151	
152	    const stateData: OAuthState = JSON.parse(storedData);
153	    if (Date.now() - stateData.timestamp > STATE_EXPIRY_MS) {
154	      sessionStorage.removeItem(STATE_STORAGE_KEY);
155	    }
156	  } catch {
157	    // If parsing fails, remove the corrupted data
158	    sessionStorage.removeItem(STATE_STORAGE_KEY);
159	  }
160	}
