16	interface PasswordSignInFormProps {
17	  redirectPath?: string;
18	}
19	
20	function PasswordSignInForm({ redirectPath }: PasswordSignInFormProps) {
21	  const t = useTranslate();
22	  const navigateTo = useNavigateTo();
23	  const { initialize } = useAuth();
24	  const actionBtnLoadingState = useLoading(false);
25	  const [username, setUsername] = useState("");
26	  const [password, setPassword] = useState("");
27	
28	  const handleFormSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
29	    e.preventDefault();
30	
31	    if (username === "" || password === "") {
32	      return;
33	    }
34	
35	    if (actionBtnLoadingState.isLoading) {
36	      return;
37	    }
38	
39	    try {
40	      actionBtnLoadingState.setLoading();
41	      const response = await authServiceClient.signIn({
42	        credentials: {
43	          case: "passwordCredentials",
44	          value: { username, password },
45	        },
46	      });
47	      // Store access token from login response
48	      if (response.accessToken) {
49	        setAccessToken(response.accessToken, response.accessTokenExpiresAt ? timestampDate(response.accessTokenExpiresAt) : undefined);
50	      }
51	      await initialize();
52	      navigateTo(redirectPath || ROUTES.HOME, { replace: true });
53	    } catch (error: unknown) {
54	      handleError(error, toast.error, {
55	        fallbackMessage: "Failed to sign in.",
56	      });
57	    }
58	    actionBtnLoadingState.setFinish();
59	  };
60	
61	  return (
62	    <form className="flex w-full flex-col gap-4" onSubmit={handleFormSubmit}>
63	      <CredentialFields
64	        idPrefix="signin"
65	        username={username}
66	        password={password}
67	        passwordAutoComplete="current-password"
68	        readOnly={actionBtnLoadingState.isLoading}
69	        onUsernameChange={setUsername}
70	        onPasswordChange={setPassword}
71	      />
72	      <Button type="submit" disabled={actionBtnLoadingState.isLoading}>
73	        {t("common.sign-in")}
74	        {actionBtnLoadingState.isLoading && <LoaderIcon className="ml-1 h-4 w-auto animate-spin opacity-60" />}
75	      </Button>
76	    </form>
77	  );
78	}
79	
80	export default PasswordSignInForm;
